    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, k = p.peak || 3;
      const evDay = i.dau * 1e6 * i.perUser * growth, ev = evDay / 86400, gbDay = (evDay * i.evKB) / 1e6;
      return { growth, k, evDay, ev, peakEv: ev * k, gbDay, kafkaTB: (gbDay * i.retention * RF) / 1000, q: i.dashQ, retention: i.retention };
    },

